import { fileURLToPath } from "node:url";
import { searchForWorkspaceRoot } from "vite";
import { defineConfig } from "vitest/config";

const fake = fileURLToPath(new URL("./test/fake-render-wasm.ts", import.meta.url));

export default defineConfig({
  resolve: {
    // The renderer is generated by `pnpm build:render`: tests use a fake instead.
    alias: [
      // The URLs of the renderer's files, which the fake module never loads.
      { find: /^@ludenea\/render-wasm\/.*\?url$/, replacement: `${fake}?url` },
      { find: "@ludenea/render-wasm", replacement: fake },
    ],
    // The physics crate's engine plugin, tested here, sits outside any package: resolve the shared
    // modules it imports from this package.
    dedupe: ["react", "@ludenea/editor-shell", "@ludenea/control-client"],
  },
  // That plugin also sits outside the pnpm workspace, which is all Vite loads files from by
  // default. Without this a run with a cold module cache (after an install or a build) cannot
  // load it; later runs only passed because they reused the cached transform.
  server: { fs: { allow: [searchForWorkspaceRoot(process.cwd()), fileURLToPath(new URL("../../../crates", import.meta.url))] } },
  test: { name: "editor-builtins", environment: "jsdom", setupFiles: ["./test/setup.ts"] },
});
